      .map(match => ({
        id: Number(match[1]),
        disabled: match[0].includes(' disabled'),
        options: [...match[2].matchAll(/<option(?: selected)?>(\w+)<\/option>/g)].map(option => option[1]),
        selected: /<option selected>(\w+)<\/option>/.exec(match[2])[1],
      }));
